// Shared intake contract: descriptions are authored and reviewed, never inferred
// from filenames or generated by slicing a generic summary at display time.
import productionSnapshot from '../data/production-search-snapshot.json' with { type: 'json' };
const published = new Map(productionSnapshot.rows.map((row) => [row[0], row]));

export function validateImportedEditorial(collections) {
  const issues = [];
  for (const collection of collections) {
    const titles = new Set(), descriptions = new Set();
    for (const item of collection.items) {
      const fail = (message) => issues.push(`${item.id}: ${message}`);
      // These finite records retain previously published content whose full
      // source-review evidence is absent in this checkout. They cannot admit a
      // new item or new copy, and are never represented as a fresh visual review.
      if (collection.preservedProduction) {
        const row = published.get(item.id);
        if (!row) { fail('Preserved item is absent from the production snapshot'); continue; }
        const [id,title,subject,keyword,summary,category,path,preview,memberships,assets,paperSha,paperKind,calendarYear,useKind] = row;
        const prior = {id,title,subject,keyword,summary,category,path,preview,memberships,assets,paperSha,paperKind,calendarYear,useKind};
        if (JSON.stringify(item.preservedSearch) !== JSON.stringify(prior)) fail('Preserved production evidence changed');
        if (item.title !== title || item.summary !== summary || item.intro !== summary || item.detail_path !== path || item.preview !== preview) fail('Preserved production content changed');
        const hashes = Object.fromEntries(Object.entries(item.assets || {}).map(([format, asset]) => [format,asset.sha256]));
        const expected = JSON.parse(assets);
        if (Object.keys(hashes).length !== Object.keys(expected).length || Object.entries(expected).some(([format, sha]) => hashes[format] !== sha)) fail('Preserved original checksums changed');
        if (item.editorial_review || item.description_paragraphs?.length) fail('A preserved item requires a fresh source review before adding reviewed content');
        continue;
      }
      for (const key of ['title', 'intro', 'alt']) {
        if (typeof item[key] !== 'string' || !item[key].trim()) fail(`Missing ${key}`);
      }
      if (!Array.isArray(item.description_paragraphs) || item.description_paragraphs.length < 2 ||
        item.description_paragraphs.some(p => typeof p !== 'string' || !p.trim())) {
        fail('Provide expanded paragraphs about this template and how to use its contents');
      }
      if (item.summary !== item.intro) fail('Summary and introduction must share the reviewed short copy');
      const description = JSON.stringify(item.description_paragraphs);
      if (titles.has(item.title)) fail('Duplicate title in collection');
      if (descriptions.has(description)) fail('Duplicate expanded description in collection');
      titles.add(item.title); descriptions.add(description);
      const review = item.editorial_review;
      if (review?.status !== 'source-reviewed') fail('Source review required');
      for (const [format, asset] of Object.entries(item.assets || {})) {
        if (review?.source_sha256?.[format] !== asset.sha256) fail(`Stale ${format} source review`);
      }
      for (const key of ['title', 'intro', 'description_paragraphs', 'alt']) {
        if (JSON.stringify(review?.reviewed_content?.[key]) !== JSON.stringify(item[key])) fail(`Review required after changing ${key}`);
      }
    }
  }
  if (issues.length) throw new Error(`Imported editorial validation failed:\n${issues.join('\n')}`);
  return true;
}
